import java.util.*;

public class P2 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int totalLength = sc.nextInt();
        sc.nextLine();
        String inputLine = sc.nextLine();

        int maxWordLen = 0;
        int currentWordLen = 0;
        int totalWordsCount = 0;
        int parenthesesLevel = 0;
        boolean outsideWordFlag = false;
        boolean insideWordFlag = false;
        boolean inParenthesesFlag = false;

        for (int i = 0; i < totalLength; i++) {
            char ch = inputLine.charAt(i);
            if (ch == '(') {
                inParenthesesFlag = true;
                parenthesesLevel++;
                if (maxWordLen < currentWordLen)
                    maxWordLen = currentWordLen;
                currentWordLen = 0;
                outsideWordFlag = false;
            } else if (ch == ')') {
                inParenthesesFlag = false;
                parenthesesLevel = 0;
                if (parenthesesLevel > 0) {
                    totalWordsCount++;
                }
            } else {
                if (parenthesesLevel > 0) {
                    inParenthesesFlag = true;
                }
            }

            if (i == totalLength)
                break;

            if (ch != ')' && ch != '(') {
                if (!inParenthesesFlag) {
                    if (ch == '_') {
                        if (maxWordLen < currentWordLen)
                            maxWordLen = currentWordLen;
                        currentWordLen = 0;
                        outsideWordFlag = false;
                    } else {
                        outsideWordFlag = true;
                    }

                    if (outsideWordFlag) {
                        currentWordLen++;
                    }
                } else {
                    outsideWordFlag = false;
                    if (ch == '_') {
                        if (parenthesesLevel > 0)
                            totalWordsCount++;
                        parenthesesLevel = 0;
                        insideWordFlag = false;
                    } else {
                        insideWordFlag = true;
                    }

                    if (insideWordFlag) {
                        parenthesesLevel++;
                    }
                }
            }
        }

        if (maxWordLen < currentWordLen)
            maxWordLen = currentWordLen;

        System.out.println(maxWordLen + " " + totalWordsCount);
    }
}
